// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzer will supply an arbitrary caller address 'caller'
    function testFuzz_property(address caller) public {
        // keep domain wide but avoid zero to ensure meaningful EOA caller
        vm.assume(caller != address(0));

        // The reference contract initializes owner only via initialize, which is protected by initializer.
        // In constructor of C, _disableInitializers() was called so initialize() must be invoked to set owner.
        // We (the test) are going to act as the factory/initializer by calling initialize from an account.

        // Choose deployer as this test contract's address (address(this)). We need to call initialize as msg.sender
        // so that owner becomes address(this) in the reference contract. Use vm.prank to simulate the caller initializing.
        vm.prank(address(this));
        c.initialize(1, 42, "v", address(this));

        // Now in the correct contract, owner() should always return the stored owner (address(this)), regardless of who calls.
        // For the mutant, owner() returns msg.sender and thus will return 'caller' when invoked by that caller.

        // Query owner() as the fuzzed caller using vm.prank to simulate their call and capture returned value.
        address returnedOwner;
        vm.prank(caller);
        returnedOwner = c.owner();

        // The universal property: for any caller, the reference returns the stored owner (address(this)).
        // So returnedOwner must equal the initializer (address(this)). This will hold on reference C for all callers,
        // but will fail on mutant for any caller != address(this).
        assertTrue(returnedOwner == address(this));
    }
}

