pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed parameter: an arbitrary caller address that the fuzzer can choose
    function testFuzz_property(address caller) public {
        // admissible domain: avoid address(0) because initialization requires msg.sender non-zero
        vm.assume(caller != address(0));

        // Initialize contract as deployer (setUp used new C(), no initializer called yet).
        // The initializer expects to be called by the factory (msg.sender becomes the phiFactoryContract inside initialize)
        // We just need to initialize Ownable with some owner; initialize() calls __Ownable_init(msg.sender)
        // So call initialize with a known sender (use address(this) as factory) — must prank to emulate factory caller

        // Prepare parameters for initialize
        uint256 credChainId_ = 1;
        uint256 credId_ = 2;
        string memory verificationType_ = "v";
        address protocolFeeDestination_ = address(0x123);

        // Call initialize as if msg.sender is the factory (we'll use address(this) as factory)
        vm.prank(address(this));
        c.initialize(credChainId_, credId_, verificationType_, protocolFeeDestination_);

        // Now the stored owner should be the initializer caller (address(this)) per __Ownable_init
        address storedOwner = c.owner();

        // Now query owner() while impersonating an arbitrary fuzzed caller.
        // For the reference contract, owner() should return the same storedOwner regardless of caller.
        vm.prank(caller);
        address ownerSeenByCaller;
        try c.owner() returns (address o) {
            ownerSeenByCaller = o;
        } catch {
            // If owner() reverts for some caller, treat as different behavior: set to zero to make assertion fail for mutant
            ownerSeenByCaller = address(0);
        }

        // Single assertion: the owner observed when called by an arbitrary caller equals the stored owner.
        // This holds for the reference (always returns stored owner) but the mutant (returns msg.sender)
        // will fail when the fuzzed caller != storedOwner.
        assertTrue(ownerSeenByCaller == storedOwner);
    }
}

