    C c;
    function setUp() public { c = new C(); }

    // fuzzed boolean decides whether to pause (true) or not (false)
    function testFuzz_property(bool doPause) public {
        // keep domain wide (boolean already minimal)
        // Arrange: make caller the owner and initialize contract so pause/unpause functions usable
        // The contract's initialize is external and requires caller to be the factory; however many functions only require ownership for pause.
        // The constructor of C calls _disableInitializers, so we cannot call initialize; but pause/unPause are only protected by onlyOwner which reads owner storage set by __Ownable_init in initialize.
        // As setUp deployed C directly without initialize, owner() will be address(0) and onlyOwner will revert for any non-zero owner.
        // To allow calling pause/unPause, we need to initialize ownership by calling initialize on c. The initialize expects msg.sender to be the phiFactory (it sets owner to msg.sender in __Ownable_init). We can call initialize from this test and become owner.

        // Call initialize to set owner and other state; pass arbitrary params
        c.initialize(uint256(1), uint256(1), "vtype", address(this));

        // Act: if doPause true -> pause, else ensure unpaused
        if (doPause) {
            c.pause();
        } else {
            // ensure unpaused: call unPause which will revert if not owner? we are owner so OK
            // unPause will revert if not paused; wrap in try/catch to ignore that and ensure final state unpaused
            try c.unPause() {
                // fine
            } catch {
                // if unPause reverted because already unpaused, ignore
            }
        }

        // Observe: call paused() via try/catch to record success and returned value
        bool ok;
        bool returned;
        try c.paused() returns (bool v) {
            ok = true;
            returned = v;
        } catch {
            ok = false;
            returned = false;
        }

        // The reference implementation: paused() should succeed and return the actual stored flag which equals doPause
        // So we assert that call succeeded and returned == doPause
        assertTrue(ok && returned == doPause);
    }
}

