pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // We fuzz a boolean 'startPaused' which determines whether we call pause() first or not,
    // and a boolean 'toggle' which, if true, will call the opposite unPause()/pause() to flip state.
    // General rule: calling pause() sets paused() == true and calling unPause() sets paused() == false.
    // The reference obeys this for all inputs; the mutant that returns !paused will break for some.
    function testFuzz_property(bool startPaused, bool toggle) public {
        // Keep domain wide; no assume needed.

        // Ensure owner is this test contract because initialize uses msg.sender as owner.
        // initialize takes (credChainId_, credId_, verificationType_, protocolFeeDestination_)
        // We pick arbitrary values; they are not the deciding ones and must be fuzzable by the fuzzer
        // per instructions we keep fuzz params as booleans above.
        c.initialize(1, 2, "v", address(this));

        // At this point, paused should be false (initially unpaused). Reference: paused() == false.
        // Now possibly pause first depending on startPaused.
        if (startPaused) {
            c.pause();
        }

        // Optionally toggle state to exercise both transitions.
        if (toggle) {
            if (c.paused()) {
                c.unPause();
            } else {
                c.pause();
            }
        }

        // After the sequence above, the expected paused state is the actual stored state observed
        // by calling the contract's paused() getter. The reference returns the stored value; the mutant
        // returns the inverse. We assert that paused() equals the stored state as observed via behavior
        // of pause/unPause calls. To make this a universal fact, we re-derive the expected state from
        // the sequence we executed (startPaused and toggle).

        bool expected;
        // initial false
        if (startPaused) {
            // we called pause() -> true
            expected = true;
        } else {
            expected = false;
        }
        if (toggle) expected = !expected;

        // Now query paused(); wrap in try/catch to comply with rules (though paused() is view and should not revert)
        bool ok;
        try c.paused() returns (bool p) {
            ok = (p == expected);
        } catch {
            // If paused() reverts, that would violate reference behavior; set ok to false so assert fails.
            ok = false;
        }

        // Single assertion: reference C satisfies paused() == expected for all inputs; mutant that inverts would fail on some inputs
        assertTrue(ok);
    }
}

