    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: two booleans deciding whether we call pause() and/or unPause() in some order
    function testFuzz_property(bool doPauseFirst, bool doUnpauseAfter) public {
        // admissible domain: none to restrict — booleans already minimal
        // We will drive the contract by optionally calling pause() and unPause() in an order determined by the fuzzers.

        // Ensure caller is the owner for pause/unPause (initialize makes msg.sender owner in initialize; constructor disabled initializers)
        // But note: C requires initialize() to be called before using onlyOwner — call initialize first as owner (this test contract)
        c.initialize(1, 2, "v", address(this));

        // start from known state: contract starts unpaused by initialize path; to be safe, call unPause if possible
        // onlyOwner available to this test contract since it initialized
        // Use doPauseFirst/doUnpauseAfter to create sequences that set stored paused flag to either true or false

        if (doPauseFirst) {
            c.pause(); // sets stored paused = true
        }

        if (doUnpauseAfter) {
            c.unPause(); // sets stored paused = false
        }

        // Now the GENERAL RULE: C.paused() should equal the stored paused flag which we can infer from our sequence.
        // Derive expectedStoredPaused based on the sequence we executed:
        bool expectedStoredPaused;
        if (doPauseFirst && !doUnpauseAfter) {
            expectedStoredPaused = true;
        } else {
            // covers: never paused (doPauseFirst==false), or paused then unpaused
            expectedStoredPaused = false;
        }

        // Read actual paused() return value
        bool ok;
        try c.paused() returns (bool v) {
            ok = v;
        } catch {
            // paused() is a view; it should not revert. If it reverts, consider that a failure of the reference as well,
            // but per the contract's design it should not revert. Set ok to false to make assertion meaningful.
            ok = false;
        }

        // Single assertion: the reference contract C must satisfy that paused() equals expectedStoredPaused for all fuzz inputs.
        // The mutant (which returns the inverse) will fail this assertion for some inputs (e.g., when expectedStoredPaused==true).
        assertTrue(ok == expectedStoredPaused);
    }
}

