    // fuzz tokenId and an explicit per-token configuration flag and a royaltyBPS candidate
    function testFuzz_property(uint256 tokenId, bool setPerTokenRecipient, uint16 perTokenBPS) public {
        // keep tokenId non-zero to avoid accidental default mappings for some flows, but allow zero too
        // wide domain; no tight assumptions

        // initialize contract (calls initializeRoyalties internally via initialize)
