contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz tokenId to discover a token without explicit per-token royalty config
    function testFuzz_property(uint256 tokenId) public {
        // keep tokenId wide but avoid the zero tokenId that might be default mapping zero confusion
        // allow zero too; do not overly constrain

        // Call must revert due to NotInitialized unless initialize called. initializeRoyalties is only
        // exposed via initialize in contract which also sets phiFactoryContract and protocolFeeDestination.
        // We need to initialize c so getRoyalties doesn't revert on NotInitialized.

        // Prepare initialization: initialize(uint256 credChainId_, uint256 credId_, string memory verificationType_, address protocolFeeDestination_)
        // It calls __Ownable_init(msg.sender) and sets phiFactoryContract = IPhiFactory(payable(msg.sender));
        // We must supply a valid protocolFeeDestination non-zero. We can pass address(this) as msg.sender during prank.

        // Use vm.prank to make the initializer caller be an address that will act as the factory (phiFactoryContract).
        address factory = address(this);
        vm.prank(factory);
        c.initialize(1, 2, "v", address(this));

        // After initialize, default royaltyRecipient was set via initializeRoyalties(protocolFeeDestination)
        // which in reference sets royaltyRecipient = protocolFeeDestination and default bps returned by getRoyalties is 500
        // For a tokenId that has no explicit per-token configuration (royalties[tokenId].royaltyRecipient == address(0)),
        // reference returns royaltyBPS == 500 and royaltyRecipient == protocolFeeDestination.

        // Ensure we pick a tokenId that hasn't been updated. We will also fuzz across tokenId space.

        // Query getRoyalties and assert the returned royaltyBPS equals 500 when royaltyRecipient equals stored default.
        // We perform the single assertion that must hold for the reference but will fail for the mutant when token has no per-token config.

        C.RoyaltyConfiguration memory r = c.getRoyalties(tokenId);

        // EXACTLY ONE assertion: check that when the returned royaltyRecipient equals the contract's stored protocol fee destination
        // (which the reference stored as default royaltyRecipient), the royaltyBPS must be 500.
        // We read protocolFeeDestination via public variable protocolFeeDestination.

        // If a token has an explicit per-token config (rarer), it may legitimately differ; but the rule we assert is:
        // For any tokenId, if r.royaltyRecipient == c.protocolFeeDestination() then r.royaltyBPS == 500.

        assertTrue(
            !(r.royaltyRecipient == c.protocolFeeDestination()) || (r.royaltyBPS == 500),
            "Default royalty recipient must have 500 BPS"
        );
    }
}

