pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameter: tokenId to query royalties for
    function testFuzz_property(uint256 tokenId) public {
        // admissible domain: any tokenId is allowed; no further assumptions to keep it wide

        // The reference contract guarantees that if no per-token override exists (i.e., royalties[tokenId].royaltyRecipient == address(0)),
        // getRoyalties returns a default configuration with royaltyBPS == 500 and royaltyRecipient == royaltyRecipient stored.
        // The mutant returns royaltyBPS == 0 in that default case. We therefore assert that getRoyalties(...) returns royaltyBPS != 0.
        // This holds for the correct contract for all tokenId, and the one-statement mutant will fail for some tokenIds (where no override exists).

        // Call getRoyalties and capture result
        (uint32 bps, address recipient) = c.getRoyalties(tokenId);

        // Exactly one assertion: in the reference, default royaltyBPS is non-zero (500). The mutant returns 0 for default and will cause this assertion to fail for some tokenId.
        assertTrue(bps != 0);
    }
}
